import { createContext, useContext, type ReactNode } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import type { Notification } from '@/entities/notification/types'
import { useAuth } from './AuthProvider'
import { notificationsService } from '@/integrations/supabase/notifications'

type NotificationContextValue = {
  notifications: Notification[]
  unreadCount: number
  markRead: (id: string) => void
  markAllRead: () => void
}

const NotificationContext = createContext<NotificationContextValue>({
  notifications: [],
  unreadCount: 0,
  markRead: () => {},
  markAllRead: () => {},
})

export function useNotifications() {
  return useContext(NotificationContext)
}

export function NotificationProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth()
  const qc = useQueryClient()

  const { data: notifications = [] } = useQuery({
    queryKey: ['notifications', user?.id],
    queryFn: () => notificationsService.listNotifications(user!.id),
    enabled: !!user,
  })

  const markReadMut = useMutation({
    mutationFn: (id: string) => notificationsService.markRead(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['notifications', user?.id] }),
  })

  const markAllReadMut = useMutation({
    mutationFn: async () => {
      await Promise.all(
        notifications.filter((n) => !n.read).map((n) => notificationsService.markRead(n.id))
      )
    },
    onSuccess: () => qc.invalidateQueries({ queryKey: ['notifications', user?.id] }),
  })

  const unreadCount = notifications.filter((n) => !n.read).length

  return (
    <NotificationContext.Provider value={{
      notifications,
      unreadCount,
      markRead: (id) => markReadMut.mutate(id),
      markAllRead: () => markAllReadMut.mutate(),
    }}>
      {children}
    </NotificationContext.Provider>
  )
}
